"""Conservative closed-loop target navigation policy with safety gating,
confidence verification, steering hysteresis, and bounded reacquisition memory.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Select a safe action using confirmed tracking and hysteretic steering."""

    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    previous_action = memory.get("previous_action", "")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    previous_bearing = float(memory.get("previous_bearing", 0.0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        memory["previous_bearing"] = bearing
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.93, "REACQUIRE")
        action = scan_direction
        memory["scan_direction"] = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        return emit(action, 0.76, "SEARCH")

    # Give a newly acquired track one cautious verification step.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.82, "VERIFY")

    if distance == "near":
        if (
            heading_error <= 12.0
            and abs(bearing) <= 12.0
            and identity_confidence >= 0.82
        ):
            return emit("ARRIVED", 0.96, "ARRIVED")

        if bearing < -8.0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.89, "APPROACH")
        if bearing > 8.0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.89, "APPROACH")
        if observation["corridor_center"] and heading_error <= 20.0:
            return emit("SLOW_DOWN", 0.84, "APPROACH")

    # Hysteresis prevents rapid left/right instruction flips near the centerline.
    steer_threshold = 16.0
    hold_threshold = 7.0
    if (
        previous_action == "VEER_LEFT"
        and bearing < steer_threshold
        and bearing > -hold_threshold
        and observation["corridor_left"]
    ):
        return emit("VEER_LEFT", 0.84, "APPROACH")
    if (
        previous_action == "VEER_RIGHT"
        and bearing > -steer_threshold
        and bearing < hold_threshold
        and observation["corridor_right"]
    ):
        return emit("VEER_RIGHT", 0.84, "APPROACH")

    if bearing <= -steer_threshold and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing >= steer_threshold and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.90, "APPROACH")

    if observation["corridor_center"]:
        return emit("FORWARD", 0.91, "APPROACH")
    if bearing < 0.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.80, "APPROACH")
    if bearing > 0.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.80, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
